package generator

import (
	"bytes"
	"fmt"
	"go/types"
	"strconv"
	"strings"
	"text/template"

	"golang.org/x/tools/imports"
)

const (
	generatedHeaderFmt = "// Code generated by testkit %s. DO NOT EDIT.\n"
	sourceHeaderFmt    = "// Source: %s\n"
	buildTagFmt        = "//go:build %s\n\n"
	goimportsFilename  = "generated.go"
)

// Header describes the comment block prepended to every generated file.
// The pipeline assembles a Header from the [Generator.Name], the
// command-line args, and [SourceAttribution]; consumers do not normally
// construct one directly.
type Header struct {
	// Subcommand is the generator name ("stub", "suite", ...).
	Subcommand string

	// Args is the original command-line invocation used as the source
	// trace ("stub Store" or "sentinel").
	Args string

	// SourceFile is the optional file:line[-line] attribution for
	// IDE navigation. Use [SourceAttribution] to compute it.
	SourceFile string

	// BuildTag, when non-empty, emits a //go:build <tag> directive
	// at the top of the file, before the generated-code header.
	BuildTag string

	// Directives lists every //testkit: directive on every method
	// the generator consumed, one rendered source-form line per
	// entry. The pipeline computes this via [RenderMethodDirectives]
	// from the [Pipeline.Methods] hook. Empty when the underlying
	// data has no directives.
	Directives []string
}

// FuncMap returns the shared template function map. Every generator's
// templates inherit these. Generator-specific helpers should live as
// methods on the data type passed to the template, not as additional
// FuncMap entries — keeping FuncMap minimal preserves a stable
// template surface.
func FuncMap() template.FuncMap {
	return template.FuncMap{
		"toLower":        strings.ToLower,
		"toUpper":        strings.ToUpper,
		"title":          Title,
		"camelCase":      CamelCase,
		"lowerCamelCase": LowerCamelCase,
		"snakeCase":      SnakeCase,
		"join":           strings.Join,
		"quote":          strconv.Quote,
		"isContext":      IsContextType,
		"isError":        IsErrorType,
		"isPointer":      func(t types.Type) bool { _, ok := t.(*types.Pointer); return ok },
		"isSlice":        func(t types.Type) bool { _, ok := t.Underlying().(*types.Slice); return ok },
		"isMap":          func(t types.Type) bool { _, ok := t.Underlying().(*types.Map); return ok },
		"isChan":         func(t types.Type) bool { _, ok := t.Underlying().(*types.Chan); return ok },
		"sub":            func(a, b int) int { return a - b },
		"add":            func(a, b int) int { return a + b },
		"dict":           templateDict,
		"splitLines":     func(s string) []string { return strings.Split(s, "\n") },
		"seq":            templateSeq,
	}
}

// templateSeq returns the slice [0, 1, ..., n-1] for use in
// `{{- range $i := seq $m.NonCtxParamCount }}` constructs that
// need the index for positional-arg rendering.
func templateSeq(n int) []int {
	out := make([]int, n)
	for i := range out {
		out[i] = i
	}
	return out
}

// templateDict assembles a map[string]any from alternating
// (key, value) pairs — the standard text/template idiom for passing
// multiple values to a sub-template:
//
//	{{template "x" (dict "Local" $ "Peer" .Peer)}}
//
// Returns an error when args has odd length or any key is non-string,
// surfacing typos at template parse time.
func templateDict(args ...any) (map[string]any, error) {
	if len(args)%2 != 0 {
		return nil, fmt.Errorf("dict: odd number of args (%d)", len(args))
	}
	out := make(map[string]any, len(args)/2)
	for i := 0; i < len(args); i += 2 {
		key, ok := args[i].(string)
		if !ok {
			return nil, fmt.Errorf("dict: key at index %d is not a string (%T)", i, args[i])
		}
		out[key] = args[i+1]
	}
	return out, nil
}

// NewTemplateSet returns a [template.Template] pre-loaded with the
// shared [FuncMap]. Generators parse their templates into this set with
// ParseFS to inherit the helpers.
func NewTemplateSet() *template.Template {
	return template.New("").Funcs(FuncMap())
}

// Render parses tmplText, executes it with data, prepends header, and
// formats with goimports. Useful for one-shot rendering — most
// generators use [RenderTemplate] with a pre-parsed template set.
func Render(tmplText string, data any, header Header) ([]byte, error) {
	tmpl, err := NewTemplateSet().Parse(tmplText)
	if err != nil {
		return nil, fmt.Errorf("parse template: %w", err)
	}
	return RenderTemplate(tmpl, "", data, header)
}

// RenderTemplate executes a pre-parsed template by name (empty for the
// root template), prepends the header, and formats the result with
// goimports.
//
// On goimports failure the function returns the raw unformatted output
// alongside the error, so the caller can debug template bugs without
// re-rendering.
func RenderTemplate(tmpl *template.Template, name string, data any, header Header) ([]byte, error) {
	var buf bytes.Buffer

	if header.BuildTag != "" {
		fmt.Fprintf(&buf, buildTagFmt, header.BuildTag)
	}

	fmt.Fprintf(&buf, generatedHeaderFmt, header.Subcommand)
	switch {
	case header.SourceFile != "":
		fmt.Fprintf(&buf, sourceHeaderFmt, header.SourceFile+" (testkit "+header.Args+")")
	case header.Args != "":
		fmt.Fprintf(&buf, sourceHeaderFmt, "testkit "+header.Args)
	}
	if len(header.Directives) > 0 {
		buf.WriteString("//\n")
		buf.WriteString("// Directives:\n")
		for _, d := range header.Directives {
			buf.WriteString("//   ")
			buf.WriteString(d)
			buf.WriteByte('\n')
		}
	}
	buf.WriteString("\n")

	var execErr error
	if name != "" {
		execErr = tmpl.ExecuteTemplate(&buf, name, data)
	} else {
		execErr = tmpl.Execute(&buf, data)
	}
	if execErr != nil {
		return nil, fmt.Errorf("execute template %q: %w", name, execErr)
	}

	formatted, err := imports.Process(goimportsFilename, buf.Bytes(), &imports.Options{
		Comments:  true,
		TabIndent: true,
		TabWidth:  8,
	})
	if err != nil {
		return buf.Bytes(), fmt.Errorf("goimports failed: %w\n\nraw output:\n%s", err, buf.String())
	}
	return formatted, nil
}
